import React from 'react';
import { Link } from 'react-router-dom';
import './Home.css';

function Home() {
  return (
    <main className="home-container">
      <h2>Welcome to the Food Truck Vendor Application</h2>
      <p>Discover the Best Food Trucks in Chennai & Bangalore! Join our community of skilled vendors and connect with food lovers who are eager to explore culinary delights on wheels.</p>
      <p>Whether you’re a vendor looking to share your delicious offerings or a foodie wanting to explore vibrant street food, you’ve come to the right place!</p>
      <Link to="/apply" className="apply-link">Become a Vendor</Link>
    </main>
  );
}

export default Home;
